public class Main {
    static final int MAXNODES = 510;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n_nodes = sc.nextInt();
        int max_edges_allowed = sc.nextInt();
        int mod_value = sc.nextInt();

        int[][] comb = new int[MAXNODES][MAXNODES];
