                    comb[i][j] = 1;
                } else {
                    comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % mod_value;
                }
            }
        }

        f1_vals[0] = 1;
        for (int i = 1; i <= n_nodes; i++) {
            f1_vals[i] = 0;
            g1_vals[i] = 0;
