                g1_vals[i] = (int)((g1_vals[i] + (g1_temp * (comb[j][2] + comb[i - j + 1][2]) + temp) % mod_value * comb[i - 1][j - 1]) % mod_value);
            }
            f1_vals[i] = (int)(((long)(i + 1) * f1_vals[i]) % mod_value);
        }

        g2_vals[0][0] = 1;
        for (int i = 1; i <= n_nodes; i++) {
            for (int j = 0; j <= Math.min(i, max_edges_allowed); j++) {
                f2_vals[i][j] = f2_vals[i - 1][j];
