                    f2_vals[i][j] = (int)((f2_vals[i][j] + temp_f * f1_vals[k] % mod_value * comb[j][k]) % mod_value);
                    long temp_g = (i - k != 0) ? f2_vals[i - k - 1][j - k] : 1;
                    long g_part = ((temp_g * g1_vals[k]) + ((i - k != 0) ? g2_vals[i - k - 1][j - k] : 0) * f1_vals[k]) % mod_value;
                    g2_vals[i][j] = (int)((g2_vals[i][j] + g_part * comb[j][k]) % mod_value);
                }
            }
        }

        System.out.println(g2_vals[n_nodes][max_edges_allowed]);
        sc.close();
    }
}
